    const PH_STATE_LABEL = { LIVE: 'Živá data', LAST_KNOWN_GOOD: 'Poslední ověřená', STALE_LAST_KNOWN: 'Zastaralá', UNAVAILABLE: 'Nedostupné', DENIED: 'Bez oprávnění' };
    const PH_KIND_LABEL = { HUB_DOMAIN_SERVICE: 'doménová služba hubu', HUB_COMPOSITE: 'doménová služba hubu (složená karta)', CORE_PLANNER_DERIVED: 'z plánovače Core', EXPLICIT_CALLER: 'explicitní zdroj' };
    const PH_PROVIDER_LABEL = { MISSING_PROVIDER: 'Zdroj vlastníka chybí', REGISTERED_UNVERIFIED: 'Zdroj připojen · neověřeno produkčně', BLOCKED_SENSITIVE_POLICY: 'Citlivá data · ukládání blokováno politikou' };
    function personalHomeValue(key, value) { if (value === null || value === undefined)
        return '—'; if (typeof value === 'string' && /At$|Eta$/.test(key) && Number.isFinite(Date.parse(value)))
        return new Date(value).toLocaleString(); return String(value); }
    function personalHomeCard(d, card, cov) {
        const providerState = cov?.sensitivePersistence === 'BLOCKED_POLICY' ? 'BLOCKED_SENSITIVE_POLICY' : cov?.integrationStatus || 'MISSING_PROVIDER';
        const display = Object.prototype.hasOwnProperty.call(PH_STATE_LABEL, card?.displayState) ? card.displayState : 'UNAVAILABLE', snap = card?.snapshot, busy = personalHomeUi.busy.has(d.projectionCode), err = personalHomeUi.errors[d.projectionCode];
        const fields = snap ? Object.entries(snap).filter(([k]) => k !== 'statusLabel').map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(personalHomeValue(k, v))}</dd></div>`).join('') : '';
        const canRefresh = providerState === 'REGISTERED_UNVERIFIED';
        return `<article class="ph-card ph-${esc(display.toLowerCase())}" data-ph-card="${esc(d.projectionCode)}" data-ph-state="${esc(display)}" data-ph-provider="${esc(providerState)}"><header><b>${esc(d.title || d.projectionCode)}</b><span class="ph-badge">${esc(PH_STATE_LABEL[display] || display)}</span></header>`
            + `<p class="ph-status">${esc(snap?.statusLabel || (display === 'UNAVAILABLE' ? 'Žádná ověřená data vlastníka' : '—'))}</p>${fields ? `<dl class="ph-fields">${fields}</dl>` : ''}`
            + `<footer><small>${esc(PH_PROVIDER_LABEL[providerState] || providerState)}${cov?.providerKind ? ` · ${esc(PH_KIND_LABEL[cov.providerKind] || cov.providerKind)}` : ''}${cov?.providerKind === 'HUB_COMPOSITE' ? ` · ${esc(homeInstall?.parts?.CORE_TASKS === 'DISABLED_BY_CALLER' ? 'úkoly Core vypnuty' : '+ úkoly Core (jen s ověřenou identitou)')}` : ''}${card?.lastVerifiedAt ? ` · ověřeno ${esc(new Date(card.lastVerifiedAt).toLocaleString())}` : ''}${card?.freshness && card.freshness !== 'UNKNOWN' ? ` · ${esc(card.freshness)}` : ''}</small>`
            + `${err ? (/AUTH_SESSION_|AUTH_IDENTITY_UNAVAILABLE/.test(String(err)) ? `<small class="ph-error" role="alert" data-ph-auth-required>Úkoly Core jsou chráněné ověřenou identitou. Přihlaste se (Profil → Ověřená identita). <code>${esc(String(err).match(/AUTH_[A-Z_]+/)?.[0] || 'AUTH')}</code></small>` : `<small class="ph-error" role="alert">${esc(err)}</small>`) : ''}<div class="ph-actions">${err ? (/AUTH_SESSION_|AUTH_IDENTITY_UNAVAILABLE/.test(String(err)) ? `<button class="btn" data-ph-signin>Přihlásit</button>` : '') : ''}${canRefresh ? `<button class="btn ghost" data-ph-refresh="${esc(d.projectionCode)}" ${busy ? 'disabled' : ''}>${busy ? 'Obnovuji…' : 'Obnovit ze zdroje'}</button>` : ''}<button class="btn ghost" data-ph-open="${esc(d.deepLink || d.ownerApp)}">Otevřít hub</button></div></footer></article>`;
    }
    // The ONLY place where Personal Home reads an owner provider. Called exclusively
    // from explicit user click handlers (guarded by qa/personal_shell_runtime_access_check.py).
    async function personalHomeUserRefresh(code) {
        if (!personalRuntime)
            return;
        const d = personalRuntime.descriptors().find((x) => x.projectionCode === code);
        if (!d || personalHomeUi.busy.has(code))
            return;
        personalHomeUi.busy.add(code);
        delete personalHomeUi.errors[code];
        try {
            await personalRuntime.refreshOwner({ projectionCode: d.projectionCode, ownerApp: d.ownerApp, subjectId: CURRENT_USER_ID, permissionGranted: true });
        }
        catch (error) {
            const m = String(error?.message || error);
            personalHomeUi.errors[code] = m.startsWith('OWNER_NO_SOURCE_RECORDS') ? 'Vlastník zatím nemá žádné záznamy pro tohoto uživatele' : `Obnova selhala: ${m}`;
        }
        finally {
            personalHomeUi.busy.delete(code);
        }
    }
    async function hydratePersonalHome() {
        const root = el('#personalHomeCards');
        if (!root || !personalRuntime)
            return;
        const token = ++personalHomeHydration;
        try {
            const descriptors = personalRuntime.descriptors(), coverage = personalRuntime.ownerSourceCoverage();
            // Restore durable last-known-good cards once per runtime (never as LIVE).
            if (!personalHomeRestored) {
                personalHomeRestored = true;
                const persistable = descriptors.filter((d) => !(d.sensitiveFields || []).length);
                if (persistable.length) {
                    try {
                        await personalRuntime.restoreCards({ subjectId: CURRENT_USER_ID, requests: persistable.map((d) => ({ projectionCode: d.projectionCode, subjectId: CURRENT_USER_ID, permissionGranted: true })) });
                    }
                    catch (error) {
                        personalHomeUi.errors['RESTORE'] = `Obnova uložených karet selhala: ${error?.message || error}`;
                    }
                }
            }
            const cards = personalRuntime.readCards({ subjectId: CURRENT_USER_ID, requests: descriptors.map((d) => ({ projectionCode: d.projectionCode, subjectId: CURRENT_USER_ID, permissionGranted: true })) });
            if (token !== personalHomeHydration || !root.isConnected)
                return;
            const connected = coverage.filter((c) => c.providerRegistered).length, live = cards.filter((c) => c.displayState === 'LIVE').length;
            root.innerHTML = `<div class="ph-head"><div><b>Personal Home</b><small>${connected}/${coverage.length} zdrojů připojeno · ${live} živých karet · vlastníci zůstávají zdrojem pravdy</small></div><button class="btn ghost" data-ph-refresh-all ${connected ? '' : 'disabled'}>Obnovit vše</button></div>${personalHomeUi.errors['RESTORE'] ? `<small class="ph-error" role="alert">${esc(personalHomeUi.errors['RESTORE'])}</small>` : ''}<div class="ph-grid">${descriptors.map((d, i) => personalHomeCard(d, cards[i], coverage.find((c) => c.projectionCode === d.projectionCode))).join('')}</div>`;
            root.querySelectorAll('[data-ph-refresh]').forEach(b => b.onclick = async (e) => { e.stopPropagation(); b.setAttribute('disabled', ''); await personalHomeUserRefresh(b.dataset.phRefresh || ''); void hydratePersonalHome(); });
            const all = root.querySelector('[data-ph-refresh-all]');
            if (all)
                all.onclick = async (e) => { e.stopPropagation(); all.setAttribute('disabled', ''); for (const c of coverage.filter((x) => x.providerRegistered && x.sensitivePersistence !== 'BLOCKED_POLICY'))
                    await personalHomeUserRefresh(c.projectionCode); void hydratePersonalHome(); };
            root.querySelectorAll('[data-ph-open]').forEach(b => b.onclick = e => { e.stopPropagation(); openRecordInspector(runtime.deepLinks.build({ kind: 'APP', id: b.dataset.phOpen }), { preserveSection: true }); });
            root.querySelectorAll('[data-ph-signin]').forEach(b => b.onclick = e => { e.stopPropagation(); profileModal(); });
        }
        catch (error) {
            if (token === personalHomeHydration && root.isConnected)
                root.innerHTML = `<div class="desk-empty" role="alert">Personal Home chyba: ${esc(error?.message || error)}</div>`;
        }
    }
