    async function hydrateApps() {
        const host = el('#hubNavHost');
        if (!host || !runtime || state.activeSection !== 'apps')
            return;
        const token = ++appsHydration;
        try {
            const svc = runtime.navigationContextProfiles;
            if (!svc)
                throw new Error('NavigationContextProfileService není připojen');
            const result = await svc.read({ userId: CURRENT_USER_ID, workspaceId: activeWorkspace.id });
            if (token !== appsHydration || state.activeSection !== 'apps')
                return;
            const resolved = KXNavigation.resolve(result.profile, { deviceClass: hubNavDeviceClass(), themeCode: theme().code, layoutCode: layout().code, iconStyle: effectiveIconStyle(), navigationModeRecommendation: shellPreset()?.navigation });
            const visual = KXNavigationVisual.render(applyHubLabelOverrides(resolved), { themeCode: theme().code, layoutCode: layout().code, iconStyle: effectiveIconStyle(), density: effectiveDensity });
            const retainedNavCategory = host.dataset.activeNavCategory || 'ALL';
            const existingSearch = el('[data-hub-nav-search]')?.value || '';
            host.innerHTML = visual.html;
            host.dataset.activeNavCategory = retainedNavCategory;
            host.querySelectorAll('[data-nav-category-filter]').forEach(button => button.classList.toggle('active', (button.dataset.navCategoryFilter || 'ALL') === retainedNavCategory));
            const restoredSearch = host.querySelector('[data-hub-nav-search]');
            if (restoredSearch)
                restoredSearch.value = existingSearch;
            applyHubNavSearch(host, existingSearch);
            decorateHubContext(host, result);
            decorateLiveNavigationIcons(host);
            decoratePackIcons(host);
            bindHubContextControls(result);
            const mode = el('[data-hub-nav-mode]');
            if (mode) {
                mode.value = result.profile.mode || 'AUTO';
                mode.onchange = async () => { try {
                    const exact = result.activeContext === 'ALL' ? (result.baseUserProfile || {}) : (result.userState?.profiles?.[result.activeContext] || {});
                    await runtime.actions.invoke('ACTION.CORE.NAVIGATION.CONTEXT.PROFILE.SAVE', { scopeType: 'USER', scopeId: CURRENT_USER_ID, userId: CURRENT_USER_ID, workspaceId: activeWorkspace.id, context: result.activeContext, profile: { ...exact, mode: mode.value } }, hubNavActionContext());
                    await hydrateApps();
                    toast(`Režim ${result.activeContext} uložen`);
                }
                catch (error) {
                    toast(`Menu: ${String(error?.message || error)}`);
                } };
            }
            const search = el('[data-hub-nav-search]');
            if (search) {
                search.oninput = () => applyHubNavSearch(host, search.value);
                search.onkeydown = e => { if (e.key === 'Escape') {
                    e.preventDefault();
                    search.value = '';
                    applyHubNavSearch(host, '');
                    host.focus();
                } };
            }
            const status = el('[data-hub-nav-status]');
            if (status)
                status.textContent = `${CTX(result.activeContext)} · ${visual.itemCount} položek · ${visual.groupCount} kategorií`;
            bindHubNavigation(host, result);
        }
        catch (error) {
            host.innerHTML = `<div class="empty">Navigace chyba: ${esc(error?.message || error)}</div>`;
        }
    }
