                askOut.innerHTML = res.length ? `<ul class="kx-gd-list">${res.map((r, k) => `<li><span class="kx-gd-t"><b>${esc(r.title)}</b><small>${esc(TL('ka2.kind.' + r.kind))}${r.detail ? ' · ' + esc((r.kind === 'WINDOW' ? TL('ka2.ui.findAt') : '') + r.detail) : ''}</small></span><span class="veh-actions"><button type="button" class="btn ghost compact" data-ka-ask-open="${k}">${esc(TL('pk.open'))}</button></span></li>`).join('')}</ul>` : `<p class="muted">${esc(TL('ka2.ui.noAnswer'))}</p><div class="kx-ka-try">${['CALC', 'IMPORT', 'CALENDAR', 'NOTES', 'FILES', 'SETTINGS'].map(x => { const tt = String(TL('ka2.tool.' + x)).split('|')[0]; return `<button type="button" class="chip" data-ka-try="${esc(tt)}">${esc(tt)}</button>`; }).join('')}</div>`;
