    /* hold to talk – the browser recogniser (Chrome / Edge send audio to Google / Microsoft – told once per session) */
    let kairaRec = null;
    async function kairaListen(host, on) {
        const out = host.querySelector('[data-ka-heard]');
        const SR = globalThis.SpeechRecognition || globalThis.webkitSpeechRecognition;
        if (!on) {
            try {
                kairaRec?.stop();
            }
            catch { }
            return;
        }
        if (!SR) {
            out.textContent = TL('ka.ui.noStt');
            return;
        }
        if (!kairaSttOk) {
            if (!confirm(TL('ka.ui.sttOnline')))
                return;
            kairaSttOk = true;
        }
        kairaRec = new SR();
        kairaRec.lang = 'cs-CZ';
        kairaRec.interimResults = false;
        kairaRec.maxAlternatives = 1;
        out.textContent = TL('ka.ui.listening');
        kairaRec.onresult = (e) => { const said = String(e.results?.[0]?.[0]?.transcript || '').trim(); out.textContent = `„${said}“`; void kairaCommand(said, out); };
        kairaRec.onerror = () => { out.textContent = TL('ka.ui.notHeard'); };
        try {
            kairaRec.start();
        }
        catch { }
    }
    async function kairaCommand(said, out) {
        const n = said.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
        const per = await runtime.actions.invoke('ACTION.CORE.KAIRA.PERSONA.GET', {}, KC()).catch(() => ({ voice: {} }));
        if (/co mam dnes|dnesni prehled|co me ceka/.test(n)) {
            if (kairaLast)
                kairaSpeak(kairaText(kairaLast), per.voice);
            return;
        }
        const op = n.match(/^otevri (.+)$/);
        if (op) {
            const want = op[1].trim();
            const hit = Array.from(document.querySelectorAll('[data-tree-hub]')).find(x => x.textContent.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().includes(want));
            if (hit) {
                openHubAt(String(hit.dataset.treeHub));
                kairaSpeak(TL('ka.ui.opening'), per.voice);
            }
            else
                out.textContent = TL('ka.ui.noHub');
            return;
        }
        const tk = said.match(/^p[řr]idej [úu]kol (.+)$/i);
        if (tk) {
            if (!confirm(TL('ka.ui.addTask').replace('{t}', tk[1])))
                return;
            const sp = ((await runtime.propagate.spaces(CURRENT_USER_ID)).find((x) => x.kind === 'PERSONAL') || {}).id;
            await runtime.actions.invoke('ACTION.CORE.TASK.SAVE', { title: tk[1], ownerApp: 'APP.NEXUS', spaceIds: [sp], assigneeIds: [CURRENT_USER_ID], status: 'TODO' }, { ...KC(), permissions: ['CORE.TASK.EDIT'] });
            kairaSpeak(TL('ka.ui.taskAdded'), per.voice);
            void kairaCard();
            return;
        }
        out.textContent = TL('ka.ui.notUnderstood');
    }
