    /* N2.5v: previewSeq – a late preview must not re-render over a newer state (it wiped the apply result); lastResult survives re-renders */ const impUi = { target: '', spaceId: '', texts: [], others: [], previews: [], previewSeq: 0, lastResult: '' };
