        val('quality')?.addEventListener('input', (e) => { camUi.quality = Number(e.target.value); });
        val('audio')?.addEventListener('change', (e) => { camUi.audio = e.target.checked; });
        val('gridbox')?.addEventListener('change', (e) => { camUi.grid = e.target.checked; void cameraModal(); });
        m.querySelector('[data-cam-presetsave]')?.addEventListener('click', async () => { const name = prompt(TL('cam.presetName')); if (!name)
            return; const [w, h] = camUi.res.split('x').map(Number); await runtime.actions.invoke('ACTION.CORE.CAMERA.PRESET.SAVE', { name, kind: camUi.mode === 'VIDEO' ? 'VIDEO' : camUi.mode === 'DOC' ? 'DOC' : 'PHOTO', width: w, height: h, fps: camUi.fps, format: camUi.format, quality: camUi.quality, bitrate: camUi.bitrate, audio: camUi.audio, grid: camUi.grid, timer: camUi.timer, zoom: camUi.zoom, torch: camUi.torch, deviceLabel: (devices.find((d) => d.deviceId === camUi.deviceId) || {}).label }, CC()); toast(TL('rights.saved')); void cameraModal(); });
