    /* N2.5g (user): help on every button – a short label (title) and a longer explanation (bubble after a moment / long press / keyboard
       focus); texts from the catalogue hp.<marker>.s / .l (marker = the button's data attribute, or action_<value> for data-action);
       setting ui.help.buttons: OFF · SHORT · FULL (default) */
    let helpMode = 'FULL';
    void (async () => { try {
        helpMode = String(await uSet('ui.help.buttons', 'FULL'));
    }
    catch { } })();
    const helpOf = (el) => {
        const act = el.getAttribute('data-action');
        const keys = [...(act ? ['action_' + act] : []), ...Array.from(el.attributes).map(a => a.name).filter(n => n.startsWith('data-')).map(n => n.slice(5))];
        for (const k of keys) {
            const sk = `hp.${k}.s`;
            const sh = TL(sk);
            if (sh && sh !== sk) {
                const lk = `hp.${k}.l`;
                const lg = TL(lk);
                return { short: sh, long: lg && lg !== lk ? lg : '' };
            }
        }
        return null;
    };
    function applyHelp(root) {
        if (helpMode === 'OFF')
            return;
        root.querySelectorAll('button,a.btn,label.btn,[role="button"]').forEach(el => {
            if (el.dataset.kxHelpDone)
                return;
            el.dataset.kxHelpDone = '1';
            const h = helpOf(el);
            if (!h)
                return;
            if (!el.getAttribute('title'))
                el.setAttribute('title', h.short);
            if (!el.getAttribute('aria-label') && !(el.textContent || '').trim())
                el.setAttribute('aria-label', h.short);
            if (helpMode === 'FULL' && h.long) {
                el.dataset.kxHelpLong = h.long;
                el.setAttribute('aria-description', h.long);
            }
        });
    }
    let helpTip = null, helpTimer = null;
    const hideTip = () => { clearTimeout(helpTimer); helpTip?.remove(); helpTip = null; };
    const showTip = (el) => {
        if (helpMode !== 'FULL' || !el.dataset.kxHelpLong || !el.isConnected || !el.matches(':hover'))
            return;
        hideTip();
        helpTip = document.createElement('div');
        helpTip.className = 'kx-help-tip';
        helpTip.setAttribute('role', 'tooltip');
        helpTip.innerHTML = `<b>${esc(el.getAttribute('title') || '')}</b><span>${esc(el.dataset.kxHelpLong)}</span>`;
        document.body.appendChild(helpTip);
        const r = el.getBoundingClientRect();
        const tw = helpTip.offsetWidth, th = helpTip.offsetHeight;
        helpTip.style.left = Math.max(8, Math.min(innerWidth - tw - 8, r.left + r.width / 2 - tw / 2)) + 'px';
        helpTip.style.top = (r.bottom + th + 12 < innerHeight ? r.bottom + 8 : Math.max(8, r.top - th - 8)) + 'px';
    };
