    /* N2.5t: holidays and namedays for planners (the user's countries / kinds / nameday calendars) – date → list */
    const calHolCache = new Map();
    async function calHolidays(from, to) {
        const H = globalThis.KXHolidays;
        const out = new Map();
        if (!H)
            return out;
        const hs = async (k, fb) => { try {
            const x = await runtime.settingsDefaults.explain(runtime.settings, k, [{ scopeType: 'USER', scopeId: CURRENT_USER_ID }]);
            return Array.isArray(x?.effectiveValue) ? x.effectiveValue : fb;
        }
        catch {
            return fb;
        } };
        const c = await hs('calendar.holidays.countries', ['CZ']), k = await hs('calendar.holidays.kinds', ['STATE', 'OTHER', 'SIGNIFICANT', 'CUSTOM', 'NAMEDAY']), n = await hs('calendar.namedays.calendars', ['CZ']);
        /* N2.5v: cache – the same range + settings is computed once (planners repaint after every saved event; namedays for a whole year are not cheap) */ const ck = [from, to, c.join(','), k.join(','), n.join(',')].join('|');
        const hit = calHolCache.get(ck);
        if (hit)
            return hit;
        for (let y = +from.slice(0, 4); y <= +to.slice(0, 4); y++)
            for (const h of H.chosen(y, c, k, n)) {
                if (h.date < from || h.date > to)
                    continue;
                if (!out.has(h.date))
                    out.set(h.date, []);
                out.get(h.date).push(h);
            }
        if (calHolCache.size > 40)
            calHolCache.clear();
        calHolCache.set(ck, out);
        return out;
    }
