                    msg.innerHTML = `<p><b>✓ ${esc(TL('dp.done'))}</b>${r.snapshotId ? ` · 🛟 ${esc(TL('dp.restorePoint'))}` : ''}</p><ul class="kx-gd-list">${r.sections.map((s) => `<li>${KN[s.kind] || '•'} ${esc(s.title || s.kind)} – ${s.skipped ? esc(TL('dp.skipped')) : s.error ? '⚠ ' + esc(String(s.error)) : `${s.created ?? 0} ${esc(TL('dp.new'))}${s.duplicates ? ` · ${s.duplicates} ${esc(TL('dp.dups'))}` : ''}`}</li>`).join('')}</ul>`;
