                pv.innerHTML = `<p><b>${r.created.length}</b> ${esc(TL('ics.toCreate'))} · ${r.duplicates.length} ${esc(TL('ics.dups'))}${r.errors.length ? ` · ⚠ ${r.errors.length} ${esc(TL('ics.errs'))}` : ''}</p><ul class="kx-gd-list">${r.created.map((e) => `<li><span class="kx-gd-t"><b>${esc(e.title)}</b><small>${esc(new Date(e.startsAt).toLocaleString('cs-CZ', e.allDay ? { dateStyle: 'medium' } : { dateStyle: 'medium', timeStyle: 'short' }))}${e.recurrence ? ' · ↻' : ''}${e.alarms?.length ? ' · 🔔 ' + e.alarms.map(lead).join(', ') : ''}</small></span></li>`).join('')}${r.duplicates.map((e) => `<li class="muted">↷ ${esc(e.title)} – ${esc(TL('ics.dupOne'))}</li>`).join('')}</ul>`;
