    function userLabel(id) { return USER_LABELS[id] || String(id).replace(/^USER\./, '').toLowerCase().replace(/^./, (c) => c.toUpperCase()); }
    /* person card: spaces + their tasks and events in the next 7 days (only what the viewer may see) */
    async function personCard(userId) {
        await loadUserLabels();
        const m = toolHost('person');
        const now = Date.now(), wk = now + 7 * 86400000;
        let spaces = [];
        try {
            spaces = await runtime.propagate.spaces(userId);
        }
        catch { }
        const mine = new Set((await runtime.propagate.spaces(CURRENT_USER_ID).catch(() => [])).map((x) => x.id));
        const vis = (r) => (r.spaceIds || []).some((x) => mine.has(x));
        const tasks = (await runtime.tasks.list()).filter((t) => !t.archivedAt && vis(t) && ((t.assigneeIds || []).includes(userId) || t.createdBy === userId) && t.status !== 'DONE' && (!t.dueAt || Date.parse(t.dueAt) <= wk)).slice(0, 20);
        const evs = (await runtime.calendar.list()).filter((e) => !e.archivedAt && vis(e) && ((e.attendeeIds || []).includes(userId) || e.createdBy === userId) && Date.parse(e.startsAt) >= now - 86400000 && Date.parse(e.startsAt) <= wk).slice(0, 20);
        const shared = spaces.filter((x) => mine.has(x.id));
        m.innerHTML = `<div class="modal" data-person-card="${esc(userId)}"><div class="drawer-head"><div><b>👤 ${esc(userLabel(userId))}</b><small>${esc(userId)}</small></div><button class="icon-btn" data-close>×</button></div><div class="ins-section">
        <p><b>${esc(TL('card.sharedSpaces'))}:</b> ${shared.map((x) => esc(x.name)).join(', ') || '—'}</p>
        <h4>${esc(TL('card.tasks'))} (${tasks.length})</h4>${tasks.map((t) => `<button type="button" class="row-btn" data-card-open="${esc(runtime.deepLinks.build({ kind: 'TASK', id: t.id }))}">☐ ${esc(t.title)}${t.dueAt ? ` · ${esc(new Date(t.dueAt).toLocaleDateString('cs-CZ'))}` : ''}</button>`).join('') || '<p class="muted">—</p>'}
        <h4>${esc(TL('card.events'))} (${evs.length})</h4>${evs.map((e) => `<button type="button" class="row-btn" data-card-open="${esc(runtime.deepLinks.build({ kind: 'CALENDAR_EVENT', id: e.id }))}">📅 ${esc(e.title)} · ${esc(new Date(e.startsAt).toLocaleString('cs-CZ'))}</button>`).join('') || '<p class="muted">—</p>'}</div></div>`;
        m.className = 'modal-wrap open';
        m.querySelector('[data-close]').onclick = () => { m.className = 'modal-wrap'; m.innerHTML = ''; };
        m.querySelectorAll('[data-card-open]').forEach(b => b.onclick = () => { m.className = 'modal-wrap'; m.innerHTML = ''; void openRecordInspector(String(b.dataset.cardOpen)); });
    }
    /* N2.5a: members and rights – parents / superadmin edit, children read their own rights only */
    /* a recovery key shown ONCE: print / copy; it is not stored anywhere in NEXUS */
    function showRecoveryKey(host, key) {
        host.innerHTML = `<div class="kx-recovery-key" data-recovery-key-once><b>${esc(TL('recovery.keyTitle'))}</b><code data-recovery-key-text>${esc(key)}</code><small>${esc(TL('recovery.keyOnce'))}</small><div><button class="btn compact" data-recovery-print>🖨 ${esc(TL('recovery.print'))}</button> <button class="btn ghost compact" data-recovery-copy>⧉ ${esc(TL('recovery.copy'))}</button></div></div>`;
        host.querySelector('[data-recovery-copy]').onclick = () => { try {
            navigator.clipboard?.writeText(key);
            toast(TL('recovery.copied'));
        }
        catch { } };
        host.querySelector('[data-recovery-print]').onclick = () => { const w = window.open('', '_blank', 'width=520,height=420'); if (!w)
            return; w.document.write(`<title>NEXUS – ${esc(TL('recovery.keyTitle'))}</title><body style="font-family:Arial;padding:24px"><h2>KalinumX NEXUS – ${esc(TL('recovery.keyTitle'))}</h2><p style="font-size:22px;font-family:monospace;letter-spacing:2px">${esc(key)}</p><p>${esc(TL('recovery.printNote'))}</p><p>${esc(new Date().toLocaleString('cs-CZ'))}</p></body>`); w.document.close(); w.focus(); w.print(); };
    }
    /* N2.5a: rights in the UI – hidden tabs, buttons of features that are off, the Kaira section; the core enforces the same
       (action guard) – this only stops offering what would be refused. Only for users who have a restriction (parents / superadmin: nothing scanned). */
    const TAB_ATTR = { 'data-shop-tab': 'APP.KX.SHOP', 'data-laser-tab': 'APP.KX.LASER', 'data-print3d-tab': 'APP.KX.PRINT3D', 'data-tw-tab': 'APP.KX.TIME', 'data-kx-tab': null };
    const FEATURE_ATTR = [['EXPORT', /^data-[a-z0-9-]*(export|csv)$/], ['IMPORT', /^data-[a-z0-9-]*import$/], ['PRINT', /^data-[a-z0-9-]*print$/], ['SHARE', /^data-[a-z0-9-]*share$/], ['DELETE', /^data-[a-z0-9-]*(delete|purge)$|^data-trash/], ['AI', /^data-ai-/]];
    const accessCache = new Map();
    let accessTimer = null;
    async function paintAccess() {
        if (typeof runtime === 'undefined' || !runtime)
            return;
        const HR = runtime.hubRights;
        if (!HR)
            return;
        const me = CURRENT_USER_ID;
        if (await HR.isSuperadmin(me))
            return;
        const mx = await HR.matrix();
        const restricted = (await HR.roleOf(me)) === 'CHILD' || Object.keys(mx.byUser?.[me] || {}).length > 0;
        if (!restricted)
            return;
        const lv = async (k) => { if (!accessCache.has(k))
            accessCache.set(k, await HR.levelFor(me, k)); return accessCache.get(k); };
        const off = [];
        for (const [f] of FEATURE_ATTR) {
            const k = 'F:' + f;
            if (!accessCache.has(k))
                accessCache.set(k, await HR.feature(me, f));
            if (accessCache.get(k) !== 'EDIT')
                off.push(f);
        }
        const curHub = document.querySelector('#inspector [data-hub-manual]')?.dataset.hubManual || '';
        if (off.includes('AI'))
            document.querySelectorAll('[data-section="ai"]').forEach(e => { e.style.display = 'none'; e.dataset.kxAccessHidden = 'AI'; });
        for (const el of Array.from(document.querySelectorAll('#inspector *,.modal *,#content *'))) {
            let hide = '';
            for (const a of Array.from(el.attributes)) {
                const n = a.name;
                if (n in TAB_ATTR) {
                    const hub = TAB_ATTR[n] || curHub;
                    if (hub && a.value && (await lv(`${hub}#TAB:${a.value.toUpperCase().replace(/[^A-Z0-9_.-]/g, '_')}`)) === 'HIDDEN') {
                        hide = 'TAB';
                        break;
                    }
                }
                for (const [f, re] of FEATURE_ATTR)
                    if (off.includes(f) && re.test(n)) {
                        hide = f;
                        break;
                    }
                if (hide)
                    break;
            }
            if (hide && el.style.display !== 'none') {
                el.style.display = 'none';
                el.dataset.kxAccessHidden = hide;
            }
        }
    }
    function scheduleAccess() { clearTimeout(accessTimer); accessTimer = setTimeout(() => { void paintAccess(); }, 200); }
    if (!globalThis.__kxAccessObserver) {
        globalThis.__kxAccessObserver = true;
        try {
            new MutationObserver(() => scheduleAccess()).observe(document.body, { childList: true, subtree: true });
        }
        catch { }
    }
    /* N2.5a: company structure – org chart; click a node → its panel (people, add, rename, move, archive); people → person card */
    /* N2.5c: contacts – list (search, filters), detail (⧉ on every field, 📞 ✉ 🗺 ↗, name day, QR vCard, copy all, vCard), edit, import / export */
    const ctUi = { query: '', kind: '', subtype: '', fav: false, sel: '', edit: false };
