                const nref = m.querySelector('[data-cr-new-ref]')?.value || '';
                if (nref)
                    d.relations.push({ ref: nref, kind: m.querySelector('[data-cr-new-kind]')?.value || 'RELATED' });
                d.tags = v('tags').split(',').map((x) => x.trim()).filter(Boolean);
