            const providerCards = providers.map(p => `<div class="settings-card" data-ai-provider-card="${esc(p.code)}"><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="record-meta"><div class="meta-row"><span>Kód</span><b>${esc(p.code)}</b></div><div class="meta-row"><span>Runtime adapter</span><b>${p.runtimeAdapter ? 'AVAILABLE' : 'UNAVAILABLE'}</b></div><div class="meta-row"><span>Auth</span><b>${esc(p.authModes.join(' / '))}</b></div></div></div>`).join('');
