            q('[data-propagate-quick]').innerHTML = `${fav.length ? `<div data-propagate-fav-list><small>★ ${esc(TL('propagate.fav'))}</small> ${fav.map((x) => chip(x)).join(' ')}</div>` : ''}${rec.length ? `<div data-propagate-recent><small>${esc(TL('propagate.recent'))}</small> ${rec.map((x) => chip(x)).join(' ')}</div>` : ''}`;
