            host.querySelectorAll('[data-propagate-favtoggle]').forEach((b) => b.onclick = () => { const k = b.dataset.propagateFavtoggle; st.propagateFav = st.propagateFav.includes(k) ? st.propagateFav.filter((x) => x !== k) : [...st.propagateFav, k].slice(-12); save(); drawResults(); drawQuick(); });
            bindPicks();
