            r.draggable = true;
            r.ondragstart = (e) => { drag = r.dataset.treeItem ? { kind: 'ITEM', code: r.dataset.treeItem } : { kind: 'CAT', code: String(r.dataset.treeCatCode) }; e.dataTransfer?.setData('text/plain', drag.code); r.classList.add('kx-tree-dragging'); };
            r.ondragend = () => { drag = null; r.classList.remove('kx-tree-dragging'); host.querySelectorAll('.kx-tree-drop').forEach(x => x.classList.remove('kx-tree-drop')); };
            r.ondragover = (e) => { if (!drag)
                return; e.preventDefault(); r.classList.add('kx-tree-drop'); };
