        m.style.top = (r.bottom + 6) + 'px';
        m.style.right = Math.max(8, window.innerWidth - r.right) + 'px';
        m.style.left = 'auto';
        const close = () => { m.remove(); document.removeEventListener('mousedown', outside, true); };
        const outside = (e) => { if (!m.contains(e.target) && !anchor.contains(e.target))
            close(); };
        setTimeout(() => document.addEventListener('mousedown', outside, true), 0);
        m.querySelector('[data-profile-locale]').onchange = async (e) => { try {
            await runtime.actions.invoke('ACTION.CORE.I18N.LOCALE.SET', { locale: e.target.value }, ctx);
            UI_LOCALE = await runtime.i18n.getLocale(CURRENT_USER_ID, activeWorkspace.id);
        }
        catch (x) {
            toast(String(x?.message || x));
        } close(); render(); };
