    const CALC_UNITS = { length: [['mm', .001], ['cm', .01], ['m', 1], ['km', 1000], ['in', .0254], ['ft', .3048]], mass: [['g', .001], ['kg', 1], ['t', 1000], ['lb', .45359237], ['oz', .028349523125]],
        pressure: [['Pa', 1], ['kPa', 1000], ['bar', 1e5], ['MPa', 1e6], ['psi', 6894.757293168], ['atm', 101325]], power: [['W', 1], ['kW', 1000], ['hp', 745.69987158], ['PS', 735.49875]],
        volume: [['ml', .001], ['l', 1], ['m³', 1000], ['gal', 3.785411784]], flow: [['l/min', 1 / 60], ['l/s', 1], ['m³/h', 1000 / 3600]], energy: [['Wh', 1], ['kWh', 1000], ['J', 1 / 3600], ['kcal', 1.163]], temperature: [['°C', 0], ['°F', 0], ['K', 0]] };
    function convertUnit(cat, v, from, to) { if (cat === 'temperature') {
        const c = from === '°C' ? v : from === '°F' ? (v - 32) * 5 / 9 : v - 273.15;
        return to === '°C' ? c : to === '°F' ? c * 9 / 5 + 32 : c + 273.15;
    } const u = CALC_UNITS[cat] || []; const f = u.find(x => x[0] === from)?.[1], t = u.find(x => x[0] === to)?.[1]; if (f == null || t == null)
        throw new Error('UNIT_UNKNOWN'); return v * f / t; }
    function evalBasic(expr) { const e = String(expr || '').replace(/,/g, '.').replace(/×/g, '*').replace(/÷/g, '/').trim(); if (!e || !/^[0-9+\-*/().%\s]+$/.test(e))
        throw new Error('CALC_EXPRESSION_INVALID'); const r = Function(`"use strict";return (${e.replace(/(\d+(?:\.\d+)?)%/g, '($1/100)')})`)(); if (typeof r !== 'number' || !Number.isFinite(r))
        throw new Error('CALC_EXPRESSION_INVALID'); return r; }
    function calcRegistry() {
        const out = [{ id: 'core.basic', hub: '', tags: ['basic'], core: 'basic' }, { id: 'core.units', hub: '', tags: ['units', 'convert'], core: 'units' },
            /* N2.5r: one registry for all calculators – 3D „all at once“ window, laser formulas (core engine), Finance tabs */ { id: 'p3.all', hub: 'APP.KX.PRINT3D', tags: ['3d', 'price', 'material'], core: 'calc3d' }, { id: 'laser.dpi', hub: 'APP.KX.LASER', tags: ['laser'], core: 'laser' }, { id: 'laser.time', hub: 'APP.KX.LASER', tags: ['laser', 'time'], core: 'laser' }, { id: 'laser.kerf', hub: 'APP.KX.LASER', tags: ['laser'], core: 'laser' }, { id: 'laser.cut', hub: 'APP.KX.LASER', tags: ['laser', 'time'], core: 'laser' }];
        for (const [hub, mod] of [['APP.KX.PRINT3D', globalThis.KXPrint3D], ['APP.KX.SHOP', globalThis.KXShop], ['APP.KX.TIME', globalThis.KXTrackWork], ['APP.KX.FINANCE', globalThis.KXFinanceHub]])
            for (const c of (mod?.CALCULATORS || []))
                out.push({ ...c, hub });
        return out.map(c => ({ ...c, title: TL('calc.' + c.id), desc: TL('calc.' + c.id + '.desc') }));
    }
