    function shellPresetDrawer() { const d = el('#drawer'); d.className = 'drawer open'; d.innerHTML = `<div class="drawer-head"><div><b>Předvolby celé pracovní plochy</b><small>Nejde jen o polohu menu: preset mění motiv, layout, navigaci, hustotu, ikony, písmo i celkový grafický charakter. Kdykoli lze následně doladit jednotlivé vrstvy.</small></div><button class="icon-btn" data-close>×</button></div><div class="shell-preset-grid">${(KXUI.SHELL_PRESETS || []).map(p => `<button class="shell-preset-card ${state.shellPreset === p.code ? 'selected' : ''}" data-shell-preset="${p.code}">${shellPresetPreview(p)}<b>${esc(p.name)}</b><small>${esc(p.description)}</small><em>${esc(p.sidebarMode)} · ${esc(p.iconStyle)} · ${esc(p.mood)}</em></button>`).join('')}</div>`; d.querySelector('[data-close]').onclick = () => d.classList.remove('open'); d.querySelectorAll('[data-shell-preset]').forEach(b => b.onclick = () => { applyShellPreset(b.dataset.shellPreset); shellPresetDrawer(); }); }
    function layoutPreview(l) { const count = Math.max(2, Math.min(6, l.columns + 1)); return `<div class="layout-preview structural nav-${String(l.nav).toLowerCase()} density-${String(l.density).toLowerCase()} ${l.inspector ? 'has-inspector' : 'no-inspector'}"><span class="lp-nav"></span><span class="lp-top"></span><div class="lp-grid cols-${Math.min(4, l.columns)}">${Array.from({ length: count }, () => '<i></i>').join('')}</div>${l.inspector ? '<b class="lp-inspector"></b>' : ''}</div>`; }
    function layoutDrawer() { const d = el('#drawer'); d.className = 'drawer open'; d.innerHTML = `<div class="drawer-head"><div><b>Rozložení aktuálního okna</b><small>Preview odpovídá navigaci, hustotě, sloupcům i Inspector policy.</small></div><button class="icon-btn" data-close>×</button></div><div class="layout-grid">${KXUI.LAYOUTS.map(l => `<button class="layout-card ${l.code === currentWindow().layout ? 'selected' : ''}" data-layout-code="${l.code}">${layoutPreview(l)}<b>${esc(l.name)}</b><small>${esc(l.family)} · ${esc(l.description)}</small><em class="theme-meta">${esc(l.nav)} · ${l.columns} sl. · ${esc(l.density)} · Inspector ${l.inspector ? 'DOCK' : 'OVERLAY'}</em></button>`).join('')}</div>`; d.querySelector('[data-close]').addEventListener('click', () => d.classList.remove('open')); d.querySelectorAll('[data-layout-code]').forEach(b => b.onclick = () => { currentWindow().layout = b.dataset.layoutCode; state.shellPreset = 'CUSTOM'; applyAppearance(); save(); render(); layoutDrawer(); }); }
