        m.innerHTML = `<div class="modal small"><div class="drawer-head"><div><b>${esc(w.name)}</b><small>Okno ${state.activeWindow + 1}/${state.windows.length}</small></div><button class="icon-btn" data-close>×</button></div><label>Název okna<input id="windowName" value="${esc(w.name)}"></label><button class="row-btn" data-dup><span>Duplikovat okno</span><b>＋</b></button><button class="row-btn danger" data-del ${state.windows.length <= 1 ? 'disabled' : ''}><span>Odstranit okno</span><b>×</b></button></div>`;
