        m.querySelector('[data-dup]').onclick = () => { state.windows.splice(state.activeWindow + 1, 0, { ...structuredClone(w), id: `WIN.${Date.now()}`, name: `${w.name} – kopie` }); state.activeWindow++; save(); render(); close(); };
