                navigator.geolocation.getCurrentPosition(p => void go({ lat: p.coords.latitude, lon: p.coords.longitude }), () => { homeWx.err = 'DENIED'; homeWx.at = Date.now(); done(); }, { timeout: 8000, maximumAge: 30 * 60000 });
